command:
cat > /tmp/rabbitmq.config <<'EOF'
[
  {rabbit, [
    {tcp_listeners, []},
    {ssl_listeners, [5671]},
    {ssl_options, [
      {cacertfile, "/etc/rabbitmq/tls/ca.crt"},
      {certfile,   "/etc/rabbitmq/tls/__NODE__.crt"},
      {keyfile,    "/etc/rabbitmq/tls/__NODE__.key"},
      {verify, verify_peer},
      {fail_if_no_peer_cert, true},
      {versions, ['tlsv1.2']}
    ]},
    {cluster_partition_handling, autoheal}
  ]},
  {rabbitmq_management, [
    {listener, [
      {port, 15672},
      {ip, "__NODE_IP__"}
    ]}
  ]}
].
EOF
sed -i "s/__NODE__/$NODE_NAME/g; s/__NODE_IP__/$NODE_IP/g" /tmp/rabbitmq.config
sudo cp /tmp/rabbitmq.config /etc/rabbitmq/rabbitmq.config
cat /etc/rabbitmq/rabbitmq.config

